const API_KEY = "19e67103-a527-493a-a5c2-c424533aa18e";
const key = msg.req.query.apiKey;

if (key !== API_KEY) {
    msg.statusCode = 403;
    msg.payload = { success: false, error: "Unauthorized API key" };
    return [null, msg];
}

const now = new Date();
const month = String(now.getMonth() + 1).padStart(2, '0'); 
const day = String(now.getDate()).padStart(2, '0');
const year = String(now.getFullYear()).slice(-2); 
const dateStr = `${month}${day}${year}`;
const randHex = RED.util.generateId().substring(0, 8);
const txnId = `BIN-${dateStr}-${randHex}`;

flow.set("currentTransactionID", txnId);
flow.set("pendingHttpRequest", msg);

// Trigger nodeRedTriggers.0 to start the PLC process
msg.payload = true;

setTimeout(() => {
    const req = flow.get("pendingHttpRequest");
    if (req) {
        const oldData = flow.get("finalBinArray");
        const id = flow.get("currentTransactionID");

        if (oldData) {
            req.payload = { 
                success: true, 
                transaction_id: id,
                data: oldData,
            };
            req.statusCode = 200;
        } else {
            req.payload = { 
                success: false, 
                error: "PLC timeout" 
            };
            req.statusCode = 504;
        }
        node.send([null, req]);
    }

    flow.set("pendingHttpRequest", null);
}, 10000); // Increased timeout to 10 seconds

return [msg, null];

let timer = context.get('timeoutId');
if (timer) clearTimeout(timer);

timer = setTimeout(function () {
    const data = msg.payload;

    const binKeys = Object.keys(data)
        .filter(key => key.startsWith('Bin_Data_Export['))
        .sort((a, b) => {
            const aNum = parseInt(a.match(/\[(\d+)\]/)[1]);
            const bNum = parseInt(b.match(/\[(\d+)\]/)[1]);
            return aNum - bNum;
        });

    const bins = binKeys.map(key => {
        const obj = { ...data[key] };
        delete obj.ZZZZZZZZZZBin_Data_R9;
        if (obj.DateTime && typeof obj.DateTime === 'string') {
            obj.DateTime = obj.DateTime.replace(/\\\//g, '/');
        }
        return obj;
    });

    const combined = { 
        User_Tablet_Admin: data.User_Tablet_Admin || "",
        Bin_Data_Export: bins 
        };

    flow.set("finalBinArray", combined);
    flow.set("userTabletAdmin", data.User_Tablet_Admin);

    const txnId = flow.get("currentTransactionID");
    const req = flow.get("pendingHttpRequest");

    if (req) {
        req.payload = {
            success: true,
            transaction_id: txnId,
            data: combined,
        };
        node.send([null, req]);
    } else {
        msg.payload = {
            success: true,
            transaction_id: txnId,
            data: combined,
        };
        node.send([null, msg]);
    }

    flow.set("pendingHttpRequest", null);

    // Turn off nodeRedTriggers.1
    node.send([{ payload: false }, null]);
    node.status({ text: "Trigger 1 reset", fill: "grey", shape: "dot" });
}, 1000);

context.set('timeoutId', timer);
return null;

const bins = msg.binData;
const txnId = msg.transaction_id;


if (!bins || bins.length === 0) {
    node.warn("No bin data to insert");
    return null;
}

let vals = [];
let placeholders = [];

for (let bin of bins) {
    placeholders.push("(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())");
    vals.push(
        txnId,
