    );

}

msg.topic = `INSERT INTO bin_exports 
    (transaction_id, bin_index ,bin_id, LotNum, ProductNum, 
     bin_compartmentA, bin_compartmentB, bin_compartmentC, bin_type, 
     location, status, bin_orphan, date_time, exported_at) 
    VALUES ${placeholders.join(', ')}`;
msg.payload = vals;

node.status({ text: `Inserting ${bins.length} bins`, fill: "blue", shape: "dot" });

return msg;

const payload = msg.payload;

if (!payload.success || !payload.transaction_id || !payload.data) {
    node.status({ text: "No DB insert - error response", fill: "red", shape: "dot" });
    return [null, null, msg];
}

const txnMsg = {
    topic: "INSERT INTO bin_transaction (transaction_id, export_timestamp, status) VALUES (?, NOW(), 'pending')",
    payload: [payload.transaction_id || 'unknown']
};

// Add bin_index to the original msg.payload.data.Bin_Data_Export
msg.payload.data.Bin_Data_Export = msg.payload.data.Bin_Data_Export.map((item, index) => {
    return {
        ...item,
        Bin_Index: index + 1
    };
});

const binMsg = RED.util.cloneMessage(msg);
binMsg.transaction_id = payload.transaction_id;
binMsg.binData = msg.payload.data.Bin_Data_Export;
binMsg.user_tablet_admin = msg.payload.data.User_Tablet_Admin || "";

// Send txnMsg to output 1, binMsg to output 2, and msg to output 3
return [txnMsg, binMsg, msg];

// 403: The client does not have access rights
// 400 Bad request: the server cannot or will not process the request

const API_KEY = "19e67103-a527-493a-a5c2-c424533aa18e";
let exportedTransactionId = flow.get("currentTransactionID");

// Validate API Key
let key = msg.payload.apiKey || msg.req.query.apiKey;
if (!key || key !== API_KEY) {
    msg.statusCode = 403;
    msg.payload = { success: false, error: "Unauthorized API key" };
    return [null, msg];
}

// Check if transaction_id is provided
let txnId = msg.payload.transaction_id || msg.req.query.transaction_id;
if (!txnId) {
    msg.statusCode = 400;
    msg.payload = { success: false, error: "Missing transaction_id" };
    return [null, msg];
}

// Check if there is a valid exportedTransactionID
if (!exportedTransactionId) {
    msg.statusCode = 400;
    msg.payload = {
        success : false,
        error : "No export transaction id found",
        message : "Please export data first before importing"
    }
    return [null, msg];
}

// Validate the transaction_Id
if (txnId !== exportedTransactionId) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        error: 'Transaction ID mismatch',
        message: 'The provided transaction_id does not match with the last exported transaction',
        //imported_transaction_id: txnId,
        //exported_transaction_id: exportedTransactionId
    };
    return [null, msg]
}

let data = msg.payload.data;
if (!data) {
    msg.statusCode = 400;
    msg.payload = { success: false, error: "Missing 'data' field" };
    return [null, msg];
}

let bins = data.Bin_Data_Import || [];
if (!Array.isArray(bins) || bins.length === 0) {
    msg.statusCode = 400;
    msg.payload = { success: false, error: "Invalid or empty Bin_Data_Import array" };
    return [null, msg];
}

let userTabletAdmin = data.User_Tablet_Admin || "";
flow.set("importUserTabletAdmin", userTabletAdmin);

// Use the Bin_Index from each bin object (note: capital B and I)
for (let i = 0; i < bins.length; i++) {
    if (!bins[i].Bin_Index) {
        msg.statusCode = 400;
        msg.payload = { success: false, error: `Missing Bin_Index in bin at array position ${i}` };
        return [null, msg];
    }
    // Bin_Index is already set in the incoming data, no need to reassign
    // Just validate it's a valid number between 1-36
    if (bins[i].Bin_Index < 1 || bins[i].Bin_Index > 36) {
        msg.statusCode = 400;
        msg.payload = { success: false, error: `Invalid Bin_Index ${bins[i].Bin_Index} at array position ${i}. Must be between 1-36.` };
        return [null, msg];
    }
}

flow.set("pendingImportRequest", msg);
flow.set("importTransactionId", txnId);
flow.set("importBinData", bins);
flow.set("currentTransactionID", null);
msg.transactionId = txnId;
msg.binData = bins;
msg.payload = bins;

node.status({ text: `Processing ${bins.length} bins`, fill: "blue", shape: "dot" });

return [msg, null];

const bins = msg.payload;

for (let i = 0; i < bins.length; i++) {
    const bin = bins[i];
    const idx = bin.Bin_Index;

    if (idx >= 1 && idx <= 36) {
        node.send([{
            payload: bin,
            index: idx
        }, null]);
    }
}

const userAdmin = flow.get("importUserTabletAdmin") || "";
node.send([null, null, {
    payload: userAdmin,
    isUserAdmin: true
}]);

// Send trigger to write to PLC
node.send([null, null, null, {
    payload: true
}]);

setTimeout(() => {
    const req = flow.get("pendingImportRequest");
    const txnId = flow.get("importTransactionId");

    if (req) {
        req.payload = {
            success: true,
            transaction_id: txnId,
            message: "Data imported to PLC successfully"
        };
        req.statusCode = 200;

        node.send([null, req]);

        flow.set("pendingImportRequest", null);
        flow.set("importTransactionId", null);

        node.status({ text: "Complete", fill: "green", shape: "dot" });
    }
}, 1000);

return null;

const txnId = msg.transactionId;
const bins = msg.binData;

const txnUpdate = {
    topic: "UPDATE bin_transaction SET status = 'completed', import_timestamp = NOW() WHERE transaction_id = ?",
    payload: [txnId]
};

let vals = [];
let placeholders = [];

for (let bin of bins) {
    placeholders.push("(?, ? ,?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())");
    vals.push(
        txnId,
        bin.Bin_Index,
        bin.Bin_ID ,
        bin.LotNum ,
        bin.ProductNum ,
        bin.CompartmentA ,
        bin.CompartmentB ,
        bin.CompartmentC ,
        bin.Bin_Type ,
        bin.Location ,
        bin.Status ,
        bin.Bin_Orphan ,
        bin.DateTime 
    );
}

const binInsert = {
    topic: `INSERT INTO bin_imports 
        (transaction_id, bin_index,bin_id, LotNum, ProductNum, 
         bin_compartmentA, bin_compartmentB, bin_compartmentC, bin_type, 
         location, status, bin_orphan, date_time, imported_at) 
        VALUES ${placeholders.join(', ')}`,
    payload: vals
};


return [txnUpdate, binInsert];

const txnId = flow.get("importTransactionId");

if (!txnId) {
    node.error("No Transaction ID found");
}
msg.topic = "CALL GetBinIDChanges(?)";
msg.payload = [txnId];
msg.transactionId = txnId;

node.status({ text: "Calling stored procedure", fill: "blue", shape: "dot" });

return msg;

// Get the stored procedure result
const spResult = msg.payload;

node.status({ text: "Processing SP result", fill: "blue", shape: "dot" });

if (!spResult || spResult.length === 0) {
    node.warn("No bin changes detected");
    msg.binChanges = [];
} else {

    const resultSet = spResult[0];

    if (!resultSet || resultSet.length === 0) {
        node.warn("No BinIDBeforeAfter field in result");
        msg.binChanges = [];
    } else {
        const binChangesData = resultSet[0]?.BinIDBeforeAfter;

        if (binChangesData) {
            try {
                const binChanges = binChangesData;
                msg.binChanges = binChanges;

                const plcArray = [];

                for (let i = 0; i < Math.min(binChanges.length, 11); i++) {
                    plcArray.push({
                        BinIndex_Before: binChanges[i].BinIndex_Before || 0,
                        BinIndex_After: binChanges[i].BinIndex_After || 0
                    });
                }

                // Store in flow context for PLC writing
                flow.set("binChangesForPLC", plcArray);

                node.warn(`Prepared ${plcArray.length} bin changes for PLC`);

            } catch (e) {
                node.error("Failed to process bin changes: " + e.message);
                msg.binChanges = [];
            }
        } else {
            node.warn("No BinIDBeforeAfter field in result");
            msg.binChanges = [];
        }
    }
}

// Get the pending request to send HTTP response
const req = flow.get("pendingImportRequest");
const txnId = flow.get("importTransactionId");

if (req) {
    req.payload = {
        success: true,
        transaction_id: txnId,
        message: "Data imported to PLC successfully",
        //bin_changes: msg.binChanges || [],
       // bin_changes_count: msg.binChanges ? msg.binChanges.length : 0
    };
    req.statusCode = 200;

    // Clear flow variables
    flow.set("pendingImportRequest", null);
    flow.set("importTransactionId", null);

    node.status({ text: "Complete", fill: "green", shape: "dot" });

    return [req, msg];
}

return [null, msg];

const binChanges = flow.get("binChangesForPLC");

if (!binChanges || binChanges.length === 0) {
    node.warn("No bin changes to write to PLC");
    return null;
}

// Write each bin change to the corresponding PLC array index
for (let i = 0; i < binChanges.length; i++) {
    const change = binChanges[i];

    // Send to output i to write to BinIDBeforeAfter[i]
    const outputMsg = {
        payload: {
            BinIndex_Before: change.BinIndex_Before,
            BinIndex_After: change.BinIndex_After
        },
        arrayIndex: i
    };

    // Create array of nulls with one message at position i
    const outputs = Array(11).fill(null);
    outputs[i] = outputMsg;

    node.send(outputs);
}

node.status({ text: `Wrote ${binChanges.length} changes to PLC`, fill: "green", shape: "dot" });

// Clear the flow variable
flow.set("binChangesForPLC", null);

return null;

let state = context.get('state') || false;
state = !state;
context.set('state', state);
msg.payload = state;
return msg;

node.warn('MySQL connection failed: ' + msg.error.message);
msg.payload = true;
return msg;

// ── Extract payload fields ──
// New PLC structure: Value_Real removed; ZZZZZZZZZZIQ_LogBuff1 is padding, ignore.
const {
    IncVal:     value_increment,
    Value_DINT: value_dint,
    Value_STR:  value_string,
    Tag_Name:   value_tagName,
    Datetime:   value_datetime,
    DataType:   rawDataType
} = msg.payload;

// ── Validate required field ──
if (!value_tagName || typeof value_tagName !== 'string') {
    node.error('Missing or invalid TagName in payload', msg);
    return null;
}

// ── Resolve value and dataType ──
const incomingType = (rawDataType || '').toUpperCase();
let value, dataType;

switch (incomingType) {
    case 'STR':
        value = value_string;
        dataType = 'string';
        break;
    case 'REAL':
        // PLC no longer ships Value_Real; fall back to DINT representation
        // so any  tag still flagged 'REAL' doesn't get silently dropped.
        value = value_dint;
        dataType = 'real';
        break;
    default: // INT / DINT / anything else
        value = value_dint;
        dataType = 'int';
        break;
}

// ── Sanitize table name ──
function sanitizeTableName(raw) {
    return raw
        .replace(/[^a-zA-Z0-9_]+/g, '__')
        .replace(/^_+|_+$/g, '')
        .replace(/^(\d)/, '_$1');
}

// Routing rule (unchanged from current production):
//   PLC* or AGV_Historical_*  → one table per UDT, fields share the table
//                               (split on '.', take the parent struct)
//   everything else           → one table per field (whole tag becomes table name)
const isPLCOrAGV = value_tagName.startsWith('PLC') ||
                   value_tagName.startsWith('AGV_Historical_');

const rawTableName = isPLCOrAGV
    ? value_tagName.split('.')[0]
    : value_tagName;

const tableName = sanitizeTableName(rawTableName);

if (!tableName) {
    node.error('Could not derive a valid table name from: ' + value_tagName, msg);
    return null;
}

// ── Check flow-context lookups ──
const tagNameList = flow.get('TagName') || [];
const tableLists  = flow.get('tables')  || [];

const tagExists = Array.isArray(tagNameList) &&
    tagNameList.some(obj => obj.tagName === value_tagName);

const tableExists = Array.isArray(tableLists) &&
    tableLists.some(t =>
        t.Tables_in_siroflex &&
        t.Tables_in_siroflex.toLowerCase() === tableName.toLowerCase()
    );

// PLC/AGV_Historical only need the table to exist; others need both.
const isValid = isPLCOrAGV ? tableExists : (tagExists && tableExists);

// ── Build query ──
if (isValid) {
    msg.topic = 'INSERT INTO `' + tableName +
                '` (DBTimestamp, Value, Datetime, TagName, IncVal) ' +
                'VALUES (NOW(), ?, ?, ?, ?)';
    msg.payload = [value, value_datetime, value_tagName, value_increment];
} else {
    const dbValue = dataType === 'string' ? value : String(value);
    const now = new Date().toISOString().slice(0, 19).replace('T', ' ');


    msg.topic = 'CALL siroflex.InsertIntoTagTableMapping(?,?,?,?,?,?,?);';
    msg.payload = [value_tagName, dbValue, dataType, tableName,
                   value_datetime, value_increment, now];
}

msg._meta = { value_tagName, tableName, isValid, isPLCOrAGV };

// node.warn({
//     tag: value_tagName,
//     derivedTable: tableName,
//     isPLCOrAGV: isPLCOrAGV,
//     tagExists: tagExists,
//     tableExists: tableExists,
//     isValid: isValid,
//     topic: msg.topic,
//     payloadArgs: msg.payload,
//     tablesListSize: tableLists.length,
//     plc3iInList: tableLists.some(t => t.Tables_in_siroflex &&
//                                        t.Tables_in_siroflex.toLowerCase() === 'plc3_i')
// });

return msg;

// ── Increment persistent counter
let count = flow.get('insertCount') || 0;
count++;
flow.set('insertCount', count);

node.status({ fill: 'green', shape: 'dot', text: 'Total: ' + count });

// Output 1 → Reset PLC Flag  (keep payload as false)
// Output 2 → UI display      (payload = count as string)
const msgDisplay = { payload: String(count), topic: msg.topic };

return [msg, msgDisplay];

const elapsed = Date.now() - (msg._mysqlStart || Date.now());

if (elapsed > 5000) {
    node.warn('Slow MySQL query: ' + elapsed + 'ms for ' + (msg.topic || 'unknown'));
    node.status({ fill: 'red', shape: 'dot', text: elapsed + 'ms (SLOW)' });
} else if (elapsed > 1000) {
    node.status({ fill: 'yellow', shape: 'ring', text: elapsed + 'ms' });
} else {
    node.status({ fill: 'green', shape: 'dot', text: elapsed + 'ms' });
}

delete msg._mysqlStart;
return msg;

if (flow.get('busy')) {
    flow.set('busy', false);
    flow.set('busySince', 0);
    node.status({ fill: 'green', shape: 'dot', text: 'cleared at ' + new Date().toLocaleTimeString() });
}
return null;

const STALL_THRESHOLD = 30000;    // PLC read stall
const BUSY_THRESHOLD = 15000;     // busy force-clear
const ALREADY_ALERTED_KEY = 'ethipStallAlerted';

const now = Date.now();
const lastRead = flow.get('ethipLastRead') || now;
const ageMs = now - lastRead;
const alreadyAlerted = flow.get(ALREADY_ALERTED_KEY) || false;

// Force-clear busy if it's been stuck
const busy = flow.get('busy');
const busySince = flow.get('busySince') || 0;
if (busy && (now - busySince) > BUSY_THRESHOLD) {
    node.warn('Force-clearing stuck busy after ' + (now - busySince) + 'ms');
    flow.set('busy', false);
    flow.set('busySince', 0);
}

if (ageMs > STALL_THRESHOLD) {
    node.status({ fill: 'red', shape: 'dot', text: 'STALL ' + Math.floor(ageMs / 1000) + 's' });
    if (!alreadyAlerted) {
        flow.set(ALREADY_ALERTED_KEY, true);
        node.error('ETH-IP STALL DETECTED: no PLC reads for ' + ageMs + 'ms', msg);
        return { payload: { event: 'stall_start', ageMs, timestamp: new Date().toISOString() } };
    }
} else {
    node.status({ fill: 'green', shape: 'dot', text: 'OK (' + ageMs + 'ms)' });
    if (alreadyAlerted) {
        flow.set(ALREADY_ALERTED_KEY, false);
        node.warn('ETH-IP RECOVERED');
        return { payload: { event: 'stall_recovered', timestamp: new Date().toISOString() } };
    }
}

return null;

const status = msg.status?.text || 'unknown';
const fill = msg.status?.fill || 'unknown';
const shape = msg.status?.shape || 'unknown';
const source = msg.status?.source?.name || 'unknown';

const prev = flow.get('ethipStatusLast_' + source) || '';
const current = fill + '/' + shape + '/' + status;

// Only log on change
if (prev !== current) {
    flow.set('ethipStatusLast_' + source, current);

    const logMsg = {
        timestamp: new Date().toISOString(),
        source: source,
        status: status,
        fill: fill,
        shape: shape,
        prev: prev
    };

    // Flag anything that look like a disconnect
    if (fill === 'red' || status.includes('offline') || status.includes('error') || status.includes('disconnected') || status.includes('timeout')) {
        node.error('eth-ip issue on ' + source + ': ' + status, logMsg);
    } else {
        node.warn('eth-ip status change on ' + source + ': ' + prev + ' → ' + current);
    }

    return { payload: logMsg };
}

return null;

// WATCHDOG: if busy is stuck longer than this, force-clear it
const WATCHDOG_MS = 10000;

const now = Date.now();
const busy = flow.get('busy');
const busySince = flow.get('busySince') || 0;

if (busy) {
    const stuckFor = now - busySince;
    if (stuckFor > WATCHDOG_MS) {
        node.warn('Watchdog fired: busy stuck for ' + stuckFor + 'ms, force-clearing and proceeding');
        // fall through - let this message proceed
    } else {
        node.status({ fill: 'yellow', shape: 'ring', text: 'skipped (' + stuckFor + 'ms)' });
        return null;
    }
}

flow.set('busy', true);
flow.set('busySince', now);
node.status({ fill: 'blue', shape: 'dot', text: 'processing' });
return msg;

const now = Date.now();
const currentIncVal = msg.payload.IncVal;
const flagState = msg.payload.Flag;

let totalReads = flow.get('totalReads') || 0;
let trueReads = flow.get('trueReads') || 0;
let stompEvents = flow.get('stompEvents') || 0;
let totalMissed = flow.get('totalMissed') || 0;
let firstIncVal = flow.get('firstIncVal');
let lastIncVal = flow.get('lastTrueIncVal');
let lastReadTime = flow.get('lastReadTime') || now;

totalReads++;

if (flagState === true) {
    trueReads++;

    if (firstIncVal === undefined) {
        firstIncVal = currentIncVal;
        flow.set('firstIncVal', firstIncVal);
        flow.set('testStartTime', now);
        node.warn({
            event: 'TEST_START',
            firstIncVal: firstIncVal,
            time: new Date(now).toISOString()
        });
    }

    if (lastIncVal !== undefined && lastIncVal !== currentIncVal) {
        const gap = currentIncVal - lastIncVal;
        if (gap > 1) {
            stompEvents++;
            totalMissed += (gap - 1);
            flow.set('stompEvents', stompEvents);
            flow.set('totalMissed', totalMissed);

            node.warn({
                event: 'STOMPED',
                previousIncVal: lastIncVal,
                currentIncVal: currentIncVal,
                missed: gap - 1,
                msSinceLastRead: now - lastReadTime,
                tagName: msg.payload.Tag_Name,
                runningTotalMissed: totalMissed,
                runningStompEvents: stompEvents
            });
        }
    }

    flow.set('lastTrueIncVal', currentIncVal);
}

flow.set('totalReads', totalReads);
flow.set('trueReads', trueReads);
flow.set('lastReadTime', now);

const startTime = flow.get('testStartTime');
const elapsed = startTime ? Math.round((now - startTime) / 1000) : 0;
node.status({
    fill: stompEvents > 0 ? 'yellow' : 'green',
    shape: 'dot',
    text: `${elapsed}s | reads:${trueReads} | stomps:${stompEvents} | missed:${totalMissed}`
});

return msg;

flow.set('totalReads', 0);
flow.set('trueReads', 0);
flow.set('stompEvents', 0);
flow.set('totalMissed', 0);
flow.set('firstIncVal', undefined);
flow.set('lastTrueIncVal', undefined);
flow.set('lastReadTime', undefined);
flow.set('testStartTime', undefined);

node.warn({ event: 'DIAGNOSTIC_RESET', time: new Date().toISOString() });
node.status({ fill: 'grey', shape: 'ring', text: 'reset — waiting for first read' });

return null;

const firstIncVal = flow.get('firstIncVal');
const lastIncVal  = flow.get('lastTrueIncVal');
const trueReads   = flow.get('trueReads')   || 0;
const totalReads  = flow.get('totalReads')  || 0;
