const dataColumnOrder = [];
const columnSet = new Set();

for (const result of allResults) {
    if (!Array.isArray(result)) continue;
    for (const row of result) {
        if (!row || typeof row !== "object") continue;
        for (const key of Object.keys(row)) {
            if (key === "_source") continue;
            if (!columnSet.has(key)) {
                columnSet.add(key);
                dataColumnOrder.push(key);
            }
        }
    }
}
const columnOrder = [...dataColumnOrder, "_source"];

// Step 2: Normalize all rows; missing columns become null.
// Add _source so the merged table shows which table each row came from.
