   doc.fontSize(14).font('Helvetica-Bold').text('Alarm Details');
   doc.moveDown(0.5);

   if (alarms.length === 0) {
      doc.fontSize(11).font('Helvetica-Oblique').fillColor('#666')
         .text('No alarms during this period.');
   } else {
      alarms.forEach((a, i) => {
         const time = new Date(a.timestamp).toLocaleString();
         const sevColor = a.severity === 'CRITICAL' ? '#c62828' : '#e65100';

         doc.fontSize(11).font('Helvetica-Bold').fillColor(sevColor)
            .text((i + 1) + '. ' + a.severity + ' - ' + a.type);
         doc.fontSize(9).font('Helvetica').fillColor('#666')
            .text('   ' + time);
         doc.fontSize(10).font('Helvetica').fillColor('black')
            .text('   ' + a.message);
         doc.moveDown(0.5);
      });
   }

   doc.end();
});

msg.payload = body;
msg.attachments = [{
