}

return null;

const FIELDS = [
  ['Source_MID', 'int'],
  ['Reserved', 'int'],
  ['CMD_Ack', 'int'],
  ['Queued', 'int'],
  ['Assigned', 'int'],
  ['ReqAcc_Granted', 'int'],
