  ['STR_MSG_MissionStatus2_VID', 'string'],
  ['STR_MSG_StationAccess1_STA', 'string'],
  ['STR_MSG_StationAccess1_FLG', 'string'],
  ['STR_CMD_LCAccess1_STA', 'string'],
  ['STR_CMD_LCAccess1_ACC', 'string'],
