const SETTLE_MS = 1000;  // wait for PLC to finish bursting writes

// -----------------------------------------------------------------------------
const section = msg.section;
if (!Number.isInteger(section) || section < 1 || section > 5) {
    node.error("msg.section must be integer 1..5; got " + JSON.stringify(section), msg);
    return null;
}

const data = msg.payload.value;
if (!data || typeof data !== 'object') {
    node.error("msg.payload.value must be the AGV_Current struct object", msg);
    return null;
}

const prevKey     = 'agv_prev_'     + section;
const baselineKey = 'agv_baseline_' + section;
const latestKey   = 'agv_latest_'   + section;
const timerKey    = 'agv_timer_'    + section;

function normalize(val, type) {
    if (val === null || val === undefined) {
        return type === 'int' ? 0 : '';
    }
    if (type === 'int') {
        if (typeof val === 'boolean') return val ? 1 : 0;
        const n = Number(val);
        return Number.isFinite(n) ? (n | 0) : 0;
    }
    return String(val);
}

function nowDatetime() {
    const d = new Date();
    const p = n => String(n).padStart(2, '0');
    const ms = String(d.getMilliseconds()).padStart(3, '0');
    return d.getFullYear() + '-' + p(d.getMonth()+1) + '-' + p(d.getDate()) + ' ' +
           p(d.getHours()) + ':' + p(d.getMinutes()) + ':' + p(d.getSeconds()) + '.' + ms;
}

// ---- build normalized current snapshot --------------------------------------
const current = {};
for (const [fieldName, type] of FIELDS) {
    current[fieldName] = normalize(data[fieldName], type);
}

// Always remember the most recent reading — the timer uses this when it fires
flow.set(latestKey, current);

// ---- baseline seeding -------------------------------------------------------
const hasBaseline = flow.get(baselineKey) === true;
if (!hasBaseline) {
    flow.set(prevKey, current);
    flow.set(baselineKey, true);
    node.status({ fill: 'blue', shape: 'dot',
        text: 'section ' + section + ' baseline seeded' });
    return null;
}

// ---- change detection -------------------------------------------------------
const prev = flow.get(prevKey) || {};
let anyChanged = false;
for (const [fieldName] of FIELDS) {
    if (current[fieldName] !== prev[fieldName]) {
        anyChanged = true;
        break;
    }
}

if (!anyChanged) {
    return null;
}

// ---- debounce: (re)start the settle timer -----------------------------------
const existingTimer = flow.get(timerKey);
if (existingTimer) {
    clearTimeout(existingTimer);
}

const timer = setTimeout(function () {
    const settled = flow.get(latestKey);
    if (!settled) return;

    // Did anything actually change vs. last written snapshot?
    const lastWritten = flow.get(prevKey) || {};
    let changedVsWritten = false;
    for (const [fieldName] of FIELDS) {
        if (settled[fieldName] !== lastWritten[fieldName]) {
            changedVsWritten = true;
            break;
        }
    }
    if (!changedVsWritten) {
        flow.set(timerKey, null);
        return;
    }

    const valueDatetime = nowDatetime();
    const inserts = [];
    for (const [fieldName] of FIELDS) {
        const val = settled[fieldName];
        const tagName = 'AGV_Current__' + section + '__' + fieldName;
        inserts.push({
            topic:   'INSERT INTO `' + tagName +
                     '` (DBTimestamp, Value, Datetime, TagName) VALUES (NOW(), ?, ?, ?)',
            payload: [val, valueDatetime, tagName],
        });
    }

    flow.set(prevKey, settled);
    flow.set(timerKey, null);

    node.status({ fill: 'green', shape: 'dot',
        text: 'section ' + section + ' — settled snapshot (' + inserts.length + ' fields)' });

    node.send([inserts]);
}, SETTLE_MS);

flow.set(timerKey, timer);

node.status({ fill: 'yellow', shape: 'ring',
    text: 'section ' + section + ' — change detected, settling…' });

return null;

finalize:
for (let s = 1; s <= 5; s++) {
    const t = flow.get('agv_timer_' + s);
    if (t) clearTimeout(t);
    flow.set('agv_timer_' + s, null);
}
